ento do último procedimento":"ESPERANDO AUDIENCIA DESDE 13/08/2026","Término de eventual prazo":"2026-06-15"},"processos":["8001815-97.2025.8.05.0067","8001528-37.2025.8.05.0067","8000038-43.2026.8.05.0067","8000054-94.2026.8.05.0067"]},{"rji":"256310776-77","nome":"VERONE ALVES DE JESUS CARNEIRO","especie":"DOMICILIAR","tipo":"Outra","situacao":"Vencido","data_prisao":"2025-04-11","dados":{"Andamento do último procedimento":"SISBAJUD","Término de eventual prazo":"2026-06-08","Prazo de reavaliação":"83","Dias preso (planilha)":"534"},"processos":["8000488-20.2025.8.05.0067","8000918-69.2025.8.05.0067"]}]'::jsonb)
      AS x(rji text, nome text, especie text, tipo text, situacao text, data_prisao text, dados jsonb, processos jsonb)
  LOOP
    SELECT count(*) INTO total_rji
      FROM public.reus r
     WHERE regexp_replace(COALESCE(r.rji, ''), '\s', '', 'g') = f.rji;

    FOR alvo IN
      SELECT r.id
        FROM public.reus r
       WHERE regexp_replace(COALESCE(r.rji, ''), '\s', '', 'g') = f.rji
         AND (
           total_rji = 1
           OR EXISTS (
             SELECT 1
               FROM jsonb_array_elements_text(COALESCE(f.processos, '[]'::jsonb)) p
              WHERE regexp_replace(COALESCE(r.processos_relacionados::text, ''), '\D', '', 'g')
                    LIKE '%' || regexp_replace(p, '\D', '', 'g') || '%'
           )
         )
    LOOP
      UPDATE public.reus
         SET nome = left(f.nome, 200),
             especie_cautelar = left(f.especie, 200),
             tipo_prisao = f.tipo,
             situacao = CASE WHEN f.situacao <> '' THEN left(f.situacao, 200) ELSE situacao END,
             data_prisao = COALESCE(f.data_prisao::date, data_prisao),
             dados_planilha = COALESCE(dados_planilha, '{}'::jsonb) || COALESCE(f.dados, '{}'::jsonb)
       WHERE id = alvo.id;
    END LOOP;
  END LOOP;
END $$;

-- Reforça o mapeamento para registros ativos com espécie conhecida.
UPDATE public.reus
   SET tipo_prisao = CASE
     WHEN regexp_replace(upper(unaccent_safe(COALESCE(especie_cautelar, ''))), '\s+', ' ', 'g') LIKE '%PREVENT%' THEN 'Prisão preventiva'
     WHEN regexp_replace(upper(unaccent_safe(COALESCE(especie_cautelar, ''))), '\s+', ' ', 'g') LIKE '%TEMPOR%' THEN 'Prisão temporária'
     WHEN regexp_replace(upper(unaccent_safe(COALESCE(especie_cautelar, ''))), '\s+', ' ', 'g') LIKE '%FLAGRAN%' THEN 'Prisão em flagrante'
     ELSE 'Outra'
   END
 WHERE preso = true
   AND COALESCE(especie_cautelar, '') <> '';
